#include <iostream>
#include <memory>
#include <string>

#include <boost/asio.hpp>

using boost::asio::ip::tcp;

class Pinger : public std::enable_shared_from_this<Pinger> {
 public:
  Pinger(boost::asio::io_context& io, std::string host)
      : resolver_(io), socket_(io), host_(std::move(host)) {}

  void start() {
    auto self = shared_from_this();
    resolver_.async_resolve(host_, "7000",
        [self](boost::system::error_code ec, tcp::resolver::results_type endpoints) {
          if (ec) return self->fail("resolve", ec);
          boost::asio::async_connect(self->socket_, endpoints,
              [self](boost::system::error_code ec, const tcp::endpoint&) {
                if (ec) return self->fail("connect", ec);
                self->send();
              });
        });
  }

 private:
  void send() {
    auto self = shared_from_this();
    boost::asio::async_write(socket_, boost::asio::buffer(request_),
        [self](boost::system::error_code ec, std::size_t) {
          if (ec) return self->fail("write", ec);
          boost::asio::async_read_until(self->socket_, boost::asio::dynamic_buffer(self->line_), '\n',
              [self](boost::system::error_code ec, std::size_t) {
                if (ec) return self->fail("read", ec);
                std::cout << self->host_ << ": " << self->line_;
              });
        });
  }

  void fail(const char* what, boost::system::error_code ec) {
    std::cerr << host_ << ": " << what << " failed: " << ec.message() << "\n";
  }

  tcp::resolver resolver_;
  tcp::socket socket_;
  std::string host_;
  std::string request_ = "PING\r\n";
  std::string line_;
};

int main() {
  boost::asio::io_context io;
  for (const char* host : {"db1.internal", "db2.internal", "db3.internal"}) {
    std::make_shared<Pinger>(io, host)->start();
  }
  io.run();
}

