#include <iostream>
#include <string>
#include <string_view>

#include <boost/asio.hpp>

using boost::asio::awaitable;
using boost::asio::use_awaitable;
using boost::asio::ip::tcp;

awaitable<void> ping(std::string host) {
  auto executor = co_await boost::asio::this_coro::executor;
  tcp::resolver resolver(executor);
  tcp::socket socket(executor);

  auto endpoints = co_await resolver.async_resolve(host, "7000", use_awaitable);
  co_await boost::asio::async_connect(socket, endpoints, use_awaitable);
  co_await boost::asio::async_write(socket, boost::asio::buffer(std::string_view("PING\r\n")), use_awaitable);

  std::string line;
  co_await boost::asio::async_read_until(socket, boost::asio::dynamic_buffer(line), '\n', use_awaitable);
  std::cout << host << ": " << line;
}

int main() {
  boost::asio::io_context io;
  for (const char* host : {"db1.internal", "db2.internal", "db3.internal"}) {
    boost::asio::co_spawn(io, ping(host), boost::asio::detached);
  }
  io.run();
}

int main() {
  boost::asio::io_context io;
  for (const char* host : {"db1.internal", "db2.internal", "db3.internal"}) {
    boost::asio::co_spawn(io, ping(host), [host](std::exception_ptr error) {
      if (!error) return;
      try {
        std::rethrow_exception(error);
      } catch (const boost::system::system_error& e) {
        std::cerr << host << ": " << e.code().message() << "\n";
      }
    });
  }
  io.run();
}
